var alarmType = metadata.alarmType != null ? metadata.alarmType : 'ALERT';
var clinic = metadata.clinic_name != null ? metadata.clinic_name : 'Unknown Clinic';
var temp = msg.temp_internal != null ? toFixed(msg.temp_internal, 1) + '°C' : 'N/A';
var batt = msg.battery_soc != null ? msg.battery_soc + '%' : 'N/A';
var lat = metadata.clinic_lat != null ? metadata.clinic_lat : (msg.latitude != null ? msg.latitude : '');
var lon = metadata.clinic_lon != null ? metadata.clinic_lon : (msg.longitude != null ? msg.longitude : '');
var mapsLink = (lat != '' && lon != '') ? 'https://maps.google.com/?q=' + lat + ',' + lon : 'Location unavailable';
var phone = metadata.alert_whatsapp != null ? metadata.alert_whatsapp : '';
var body = '🚨 CoolCycle ALERT\nClinic: ' + clinic + '\nIssue: ' + alarmType + '\nTemp: ' + temp + '\nBattery: ' + batt + '\nLocation: ' + mapsLink;
msg.wa_to = 'whatsapp:+' + phone.replace(/\D/g, '');
msg.wa_body = body;
return {msg: msg, metadata: metadata, msgType: msgType};
